 contourSource=d/'attempts/direct-ai-short-prompt/candidate-4x.png';a=np.array(Image.open(contourSource).convert('RGBA'));hasRGB=np.any(a[:,:,:3]!=0,axis=2);assert not np.any(hasRGB&(a[:,:,3]==0));mask=np.zeros_like(a);mask[:,:,3]=np.where(hasRGB,0,255).astype('uint8');maskImage=Image.fromarray(mask);maskImage.save(d/'rgb-window-black-stencil-4x.png',compress_level=1)
 crop=five.crop((x*4,y*4,(x+w)*4,(y+h)*4));composite=Image.alpha_composite(crop,maskImage);composite.save(d/'rgb-window-composite-before-key-4x.png',compress_level=1);out=np.array(composite);black=np.all(out[:,:,:3]==0,axis=2);out[:,:,3]=np.where(black,0,255);out[black,:3]=0;dest=d/'candidate-4x.png';Image.fromarray(out).save(dest,compress_level=1);ref=np.array(crop);visible=out[:,:,3]>0;assert np.array_equal(out[:,:,:3][visible],ref[:,:,:3][visible]);assert set(np.unique(out[:,:,3])).issubset({0,255})
 record={'id':key,'candidate':dest.as_posix(),'sha256':sha(dest),'logicalSize':[w,h],'physicalSize':[w*4,h*4],'baseline':E[key]['current']['path'],'kind':'images','group':'场景与地图','original':E[key]['original'],'method':'按用户要求：原高清草坪RGB非零处变为透明镂空，RGB全零处变为纯黑；离线覆盖五行地图对应裁图，再把合成结果纯黑像素改成RGBA(0,0,0,0)。不复制源alpha、不叠加边缘明暗。','sources':[source.as_posix(),contourSource.as_posix(),(d/'rgb-window-black-stencil-4x.png').as_posix()],'mapLogicalRect':[x,y,w,h],'originalDrawLogical':[x-220,y],'mapCropPixels4x':[x*4,y*4,w*4,h*4],'RGBPresenceRule':'R != 0 OR G != 0 OR B != 0, tested on original HD grass; verified all source alpha-zero pixels have RGB0','finalAlphaRule':'RGB exactly(0,0,0) -> RGBA0; every other pixel opaque','sourceAlphaCopied':False,'edgeShading':False,'visibleRGBPixelIdenticalToMap':True,'externalRuntimeMask':None,'reviewStatus':'pending','runtime2xUsedAsSource':False,'runtimeBindingChanged':False,'sourceOpaquePureBlackPixelsNowCutOut':int(((~hasRGB)&(a[:,:,3]>0)).sum())};(d/'recipe.json').write_text(json.dumps(record,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');i=next(i for i,r in enumerate(doc['items']) if r['id']==key);doc['items'][i]=record;E[key]['repairCandidate'].update(sha256=record['sha256'],reviewStatus='pending');E[key]['repairCandidate'].pop('thumbnail',None);proof.append({'id':key,'visibleRGBMatchesMap':True,'alphaIs0Or255':True,'transparentRGBIsZero':True,'cutOutSourceBlackPixels':record['sourceOpaquePureBlackPixelsNowCutOut'],'sha256':record['sha256']})
